flowchart TD
    A[Define the research or analysis goal] --&gt; B[Describe the task to the AI assistant]

    B --&gt; C[AI proposes an approach]
    C --&gt; D[AI generates or modifies R code]
    D --&gt; E[Run the code in RStudio]

    E --&gt; F{Does the code run?}

    F -- No --&gt; G[Give the error and relevant context to the AI]
    G --&gt; C

    F -- Yes --&gt; H{Is the method scientifically valid?}

    H -- No --&gt; I[Review assumptions, data and analytical method]
    I --&gt; B

    H -- Yes --&gt; J[Inspect plots, tables and model diagnostics]

    J --&gt; K{Does the output answer the research question?}

    K -- No --&gt; L[Refine the prompt or analytical approach]
    L --&gt; B

    K -- Yes --&gt; M[Refactor and simplify the code]
    M --&gt; N[Add tests, comments and documentation]
    N --&gt; O[Save code, outputs and session information]
    O --&gt; P[Produce reproducible research output]

    classDef human fill:#d9eaf7,stroke:#2f5597,color:#000;
    classDef ai fill:#fce4d6,stroke:#c65911,color:#000;
    classDef decision fill:#fff2cc,stroke:#bf9000,color:#000;
    classDef output fill:#e2f0d9,stroke:#548235,color:#000;

    class A,B,E,G,I,J,L human;
    class C,D,M,N ai;
    class F,H,K decision;
    class O,P output;





